<?php require __DIR__.'/bootstrap.php'; $rows=$pdo->query('SELECT title,subject,grade,description,file_name FROM summaries WHERE published=1 ORDER BY created_at DESC')->fetchAll(); ?><!doctype html><html lang="he" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="style.css"><title>סיכומים | מחברת פתוחה</title></head><body><header><a class="brand" href="index.php">מחברת פתוחה</a><nav><a href="request.php">בקשי סיכום</a></nav></header><main><h1>סיכומים</h1><div class="cards"><?php foreach($rows as $s): ?><article><div class="cover">PDF <b><?=e($s['subject'])?></b></div><small><?=e($s['grade'])?></small><h3><?=e($s['title'])?></h3><p><?=e($s['description'])?></p><a href="uploads/<?=rawurlencode($s['file_name'])?>" target="_blank">לצפייה ולהורדה ←</a></article><?php endforeach ?></div></main></body></html>
